// Generate arbitrary 64-bit inputs a and b
long long a = *FUZZ_PARAM(long long);
long long b = *FUZZ_PARAM(long long);

// Prepare lvalue references for outputs x and y
long long x = 0;
long long y = 0;

// Call the target
long long d = shah::extended_euclid(a, b, x, y);

// Validate Bezout identity using 128-bit intermediates to avoid overflow
__int128 lhs = (__int128)a * (__int128)x + (__int128)b * (__int128)y;
FUZZ_ASSERT(lhs == (__int128)d, "Extended Euclid: Bezout identity failed");

// Validate that d equals gcd(|a|,|b|) and is non-negative
auto ugcd = [] (long long u, long long v) {
    unsigned long long x = (u < 0) ? -(unsigned long long)u : (unsigned long long)u;
    unsigned long long y = (v < 0) ? -(unsigned long long)v : (unsigned long long)v;
    while (y) { unsigned long long t = x % y; x = y; y = t; }
    return (long long)x;
};
long long expected_d = ugcd(a, b);
FUZZ_ASSERT(d == expected_d, "Extended Euclid: gcd mismatch");

// Generate inputs a and m, with m > 0 per contract
long long a = *FUZZ_PARAM(long long);
unsigned long long mu = *FUZZ_PARAM(unsigned long long);
long long m = (long long)((mu % (unsigned long long)(LLONG_MAX)) + 1ULL); // ensure m in [1, LLONG_MAX]

long long inv = shah::mod_inverse(a, m);

// Compute gcd(|a|,|m|)
auto ugcd = [] (long long u, long long v) {
    unsigned long long x = (u < 0) ? -(unsigned long long)u : (unsigned long long)u;
    unsigned long long y = (v < 0) ? -(unsigned long long)v : (unsigned long long)v;
    while (y) { unsigned long long t = x % y; x = y; y = t; }
    return (long long)x;
};
long long g = ugcd(a, m);

if (g != 1) {
    // Inverse should not exist
    FUZZ_ASSERT(inv == -1, "mod_inverse: expected -1 when gcd != 1");
} else {
    // Validate inverse properties when it exists
    FUZZ_ASSERT(inv >= 0 && inv < m, "mod_inverse: inverse out of range [0, m-1]");
    __int128 prod = (__int128)a * (__int128)inv;
    long long mod1 = (long long)((prod % (__int128)m + (__int128)m) % (__int128)m);
    FUZZ_ASSERT(mod1 == 1 % m, "mod_inverse: (a*inv)%m != 1");
}

// Generate inputs x, n, mod with mod > 0 and n >= 0
long long x = *FUZZ_PARAM(long long);
unsigned long long nu = *FUZZ_PARAM(unsigned long long);
unsigned long long modu = *FUZZ_PARAM(unsigned long long);
long long mod = (long long)((modu % (unsigned long long)(LLONG_MAX)) + 1ULL); // [1, LLONG_MAX]
long long n = (long long)(nu & 0x7FFFFFFFFFFFFFFFULL); // force non-negative within signed range

long long r = shah::power_mod(x, n, mod);

// Always within residue class [0, mod-1]
FUZZ_ASSERT(r >= 0 && r < mod, "power_mod: result out of range [0, mod-1]");

// Reference computation (fast binary exponentiation) for cross-check
auto ref_pow = [&](){
    __int128 base = ( (__int128)x % (__int128)mod + (__int128)mod ) % (__int128)mod;
    __int128 res = 1 % (__int128)mod;
    unsigned long long e = (unsigned long long)n; // n is non-negative
    while (e) {
        if (e & 1ULL) res = (res * base) % (__int128)mod;
        base = (base * base) % (__int128)mod;
        e >>= 1ULL;
    }
    return (long long)res;
};
long long r_ref = ref_pow();
FUZZ_ASSERT(r == r_ref, "power_mod: reference mismatch");

// Edge case: n == 0 should yield 1 % mod
if (n == 0) {
    FUZZ_ASSERT(r == (1 % mod), "power_mod: n==0 should return 1%mod");
}

// Generate arbitrary string input
std::string s = FUZZ_PARAM_STR();
std::vector<int> z = shah::z_function(s);

// Basic shape validations
FUZZ_ASSERT((size_t)z.size() == s.size(), "z_function: size mismatch");
if (!s.empty()) { FUZZ_ASSERT(z[0] == 0, "z_function: z[0] must be 0"); }

// Property checks at a few sampled indices to keep runtime light
int n = (int)s.size();
int samples = n < 3 ? n : 3;
// Derive up to three indices deterministically from extra fuzz integers
unsigned int r1 = *FUZZ_PARAM(unsigned int);
unsigned int r2 = *FUZZ_PARAM(unsigned int);
unsigned int r3 = *FUZZ_PARAM(unsigned int);
int idxs[3] = { n ? (int)(r1 % (unsigned)n) : 0, n ? (int)(r2 % (unsigned)n) : 0, n ? (int)(r3 % (unsigned)n) : 0 };
for (int k = 0; k < samples; ++k) {
    int i = idxs[k];
    if (i <= 0 || i >= n) continue; // skip 0 and out of range
    int zi = z[i];
    if (zi < 0) { FUZZ_BAIL(); }
    if (zi > n - i) { FUZZ_BAIL(); }
    // Verify prefix match of length zi
    for (int t = 0; t < zi; ++t) {
        if (s[t] != s[i + t]) { FUZZ_BAIL(); }
    }
    // If zi is not full length, next char should mismatch (standard Z invariant)
    if (i + zi < n && zi > 0) {
        if (s[zi] == s[i + zi]) { FUZZ_BAIL(); }
    }
}

