int n = par_sz == 0 ? 0 : (int)par_sz - 1;
// Count must be in [0, n]
if (cnt < 0 || cnt > n) { FUZZ_BAIL(); }

// DSU returned as output

size_t par_sz = dsu->par.size();
if (par_sz <= 1) { FUZZ_BAIL(); }
int n = (int)par_sz - 1;
int i = (int)(*FUZZ_PARAM(unsigned int) % (unsigned)n) + 1;
int j = (int)(*FUZZ_PARAM(unsigned int) % (unsigned)n) + 1;

// Capture pre-merge state
int cnt_before = dsu->count();
int si = dsu->get_size(i);
int sj = dsu->get_size(j);
bool same_before = dsu->same(i, j);

int r = dsu->merge(i, j);

if (same_before) {
    // No change expected
    if (r != -1) { FUZZ_BAIL(); }
    if (dsu->count() != cnt_before) { FUZZ_BAIL(); }
} else {
    // Merge should succeed: representative in [1..n], count decreases by 1, and i,j become connected
    if (r < 1 || r > n) { FUZZ_BAIL(); }
    if (dsu->count() != cnt_before - 1) { FUZZ_BAIL(); }
    if (!dsu->same(i, j)) { FUZZ_BAIL(); }
    // Size of the resulting component should be si + sj
    int s_after = dsu->get_size(i);
    if (s_after != si + sj) { FUZZ_BAIL(); }
}

// DSU returned as output

// Construct a DSU with n elements (1-indexed). Choose n in [1, 1024] to keep allocations modest.
unsigned int ru = *FUZZ_PARAM(unsigned int);
int n = (int)(ru % 1024u) + 1; // ensure n >= 1

shah::DSU *dsu = new shah::DSU(n);

// Basic post-construction sanity: par.size()==n+1, initial count()==n, sizes are 1
if (dsu->par.size() != (size_t)(n + 1)) { FUZZ_BAIL(); }
if (dsu->count() != n) { FUZZ_BAIL(); }
for (int i = 1; i <= n && i <= 3; ++i) { // spot-check a few to keep runtime light
    if (dsu->par[i] != i) { FUZZ_BAIL(); }
    if (dsu->get_size(i) != 1) { FUZZ_BAIL(); }
}

// Optionally perform up to three merges to diversify state while preserving invariants
unsigned int rmerges = *FUZZ_PARAM(unsigned int);
int k = (int)(rmerges % 4u); // 0..3 merges
for (int t = 0; t < k; ++t) {
    int i = (int)(*FUZZ_PARAM(unsigned int) % (unsigned)n) + 1;
    int j = (int)(*FUZZ_PARAM(unsigned int) % (unsigned)n) + 1;

    int cnt_before = dsu->count();
    int si = dsu->get_size(i);
    int sj = dsu->get_size(j);
    bool same_before = dsu->same(i, j);

    int r = dsu->merge(i, j);

    if (same_before) {
        // Already connected: merge is a no-op and returns -1; count unchanged
        if (r != -1) { FUZZ_BAIL(); }
        if (dsu->count() != cnt_before) { FUZZ_BAIL(); }
    } else {
        // Successful union: representative must be within [1..n]
        if (r < 1 || r > n) { FUZZ_BAIL(); }
        if (dsu->count() != cnt_before - 1) { FUZZ_BAIL(); }
        if (!dsu->same(i, j)) { FUZZ_BAIL(); }
        int s_after = dsu->get_size(i);
        if (s_after != si + sj) { FUZZ_BAIL(); }
    }

    // Touch find() to exercise path compression
    int root_i = dsu->find(i);
    if (root_i < 1 || root_i > n) { FUZZ_BAIL(); }
}

// Store n for potential downstream consumers (not required by API, but helpful metadata)
FUZZ_SET_ATTR_INT(dsu, "n", n);

